// The `api-compatibility` rule: the props API of every stable or deprecated component and pattern
// may only grow against the last release of @mylder/perron (docs/components/README.md, "Change").
// The API is packages/perron/api.json, generated by `npm run api` and kept fresh by `api:check`;
// this check reads that file at the latest `@mylder/perron@x.y.z` tag and compares it with the API
// the code has now. Growing is a new optional prop, a prop made optional, a wider union or a new
// base; anything else is a break. A deliberate break is a row of the "Breaking changes" table in
// the contract, not a perron-allow: an API has no line to excuse.
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { API, codeFile, readApi, type Api } from '../lib/api.ts'
import { REGISTRY, readRegistry } from '../lib/registry.ts'
import type { Check, Problem } from './lib.ts'

/** The contract, which holds the "Breaking changes" table. */
export const CONTRACT = 'docs/components/README.md'

/** One break: the component, the prop (`extends` for a base, `*` for the whole component). */
export interface Break {
  component: string
  prop: string
  message: string
}

/** What a caller of `before` could write that `after` no longer takes. */
export function compareApi(before: Api, after: Api): Break[] {
  const out: Break[] = []
  for (const [component, old] of Object.entries(before)) {
    const now = after[component]
    const add = (prop: string, message: string) => out.push({ component, prop, message })
    if (!now) {
      add('*', `${component} is gone; deprecate a component, never remove it`)
      continue
    }
    for (const base of old.extends)
      if (!now.extends.includes(base)) add('extends', `${component}Props no longer extends ${base}`)
    for (const [prop, was] of Object.entries(old.props)) {
      const is = now.props[prop]
      if (!is) add(prop, `${component} no longer has ${prop}; deprecate a prop, never remove it`)
      else if (was.optional && !is.optional) add(prop, `${component} makes ${prop} required`)
      else if (!was.type.every((m) => is.type.includes(m)))
        add(
          prop,
          `${component} narrows ${prop} from ${was.type.join(' | ')} to ${is.type.join(' | ')}`,
        )
    }
    for (const [prop, is] of Object.entries(now.props))
      if (!old.props[prop] && !is.optional)
        add(prop, `${component} adds ${prop} as a required prop`)
  }
  return out
}

const RELEASE = /^@mylder\/perron@(\d+)\.(\d+)\.(\d+)$/

/** The tag of the highest released version, prereleases left out. */
export function latestRelease(tags: string[]): string | undefined {
  const version = (t: string) => RELEASE.exec(t)!.slice(1).map(Number)
  return tags
    .filter((t) => RELEASE.test(t))
    .sort((a, b) => {
      const [x, y] = [version(a), version(b)]
      return x[0] - y[0] || x[1] - y[1] || x[2] - y[2]
    })
    .at(-1)
}

/** The rows of the table under the contract's "Breaking changes" heading. */
export function breakingChanges(text: string, file: string) {
  const rows: { component: string; prop: string }[] = []
  const problems: Problem[] = []
  const lines = text.split('\n')
  const start = lines.findIndex((l) => /^#+ Breaking changes\s*$/.test(l))
  if (start < 0) return { rows, problems }
  let seen = 0
  for (let i = start + 1; i < lines.length && !/^#/.test(lines[i]); i++) {
    if (!lines[i].startsWith('|')) continue
    // the header and the line under it
    if (seen++ < 2) continue
    const cells = lines[i]
      .split(/(?<!\\)\|/)
      .slice(1, -1)
      .map((c) => c.trim().replace(/^`|`$/g, ''))
    const [component, prop, reason] = cells
    if (!reason)
      problems.push({
        file,
        line: i + 1,
        message: `the breaking change ${component} ${prop} needs a reason`,
      })
    else rows.push({ component, prop })
  }
  return { rows, problems }
}

const git = (root: string, args: string[]) => {
  try {
    return execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: 'pipe' })
  } catch {
    return undefined
  }
}

const check: Check = {
  rule: 'api-compatibility',
  run(root) {
    const tag = latestRelease((git(root, ['tag', '--list', '@mylder/perron@*']) ?? '').split('\n'))
    if (!tag) {
      if (process.env.CI)
        return [
          {
            file: API,
            message:
              'no @mylder/perron release tag in this clone; CI checks out with fetch-depth: 0 to bring the tags',
          },
        ]
      console.warn(
        'api-compatibility: no @mylder/perron release tag in this clone (git fetch --tags); skipped',
      )
      return []
    }
    // a release from before api.json had no API to hold
    const released = git(root, ['show', `${tag}:${API}`])
    if (released === undefined) return []
    const breaks = compareApi(JSON.parse(released) as Api, readApi(root))
    const table = existsSync(join(root, CONTRACT))
      ? breakingChanges(readFileSync(join(root, CONTRACT), 'utf8'), CONTRACT)
      : { rows: [], problems: [] }
    const code = new Map(readRegistry(root).map((e) => [e.name, codeFile(e)]))
    const kept = breaks.filter(
      (b) => !table.rows.some((r) => r.component === b.component && r.prop === b.prop),
    )
    return [
      ...kept.map((b) => ({
        file: (b.prop !== '*' && code.get(b.component)) || REGISTRY,
        message: `${b.message} since ${tag}. A deliberate break is a row in ${CONTRACT}, "Breaking changes"`,
      })),
      ...table.problems,
    ]
  },
}

export default check
